  const action=view==='today'?`<a class="button" href="/api/cheques/today.pdf?date=${encodeURIComponent(report.date)}">Download PDF</a>`:'';
  const dateField=['today','yesterday'].includes(view)?`<div class="field cheque-date-field"><label for="chequeDate">Scheduled date</label><input id="chequeDate" type="date" value="${esc(report.date)}"></div>`:'';
  const rows=report.rows.map(c=>{
    const partyCell = `<div><strong>${esc(borrowerName(c)||'Borrower')}</strong></div>`;
    return `<tr><td>${partyCell}<div class="muted mini"><a class="text-link" href="#/loans/${c.account_id}">${esc(c.reference)}</a></div></td><td class="money">${fmt(c.amount_paise)}</td>${view==='today'?'':`${view==='yesterday'?'':`<td>${esc(shortDate(c.scheduled_date))}</td>`}<td>${pill(c.status==='PENDING'?'Awaiting result':c.status==='PASSED'?'Passed':'Bounced',c.status==='BOUNCED'?'red':c.status==='PENDING'?'amber':'')}</td><td>${c.status==='PENDING'&&canResolve?`<div class="result-actions"><button class="button small cheque-result" data-id="${esc(c.id)}" data-status="PASSED">Passed</button><button class="button small secondary cheque-result" data-id="${esc(c.id)}" data-status="BOUNCED">Bounced</button></div>`:'—'}</td>`}</tr>`;
  }).join('');
  const table=report.rows.length?`<div class="table-wrap"><table class="table cheque-table"><thead><tr><th>Borrower</th><th>Amount</th>${view==='today'?'':`${view==='yesterday'?'':'<th>Scheduled date</th>'}<th>Status</th><th>Result</th>`}</tr></thead><tbody>${rows}</tbody></table></div>`:empty(view==='today'?'No scheduled cheques for this date.':'No cheques in this view.');
  const yesterdayTable=report.rows.length?`<div class="yesterday-table-wrap"><table class="yesterday-table"><thead><tr><th>Borrower / Organisation</th><th>Cheque amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${report.rows.map(c=>`<tr class="yesterday-cheque-${c.status.toLowerCase()}"><td data-label="Borrower"><a class="yesterday-borrower-link" href="#/loans/${esc(c.account_id)}"><strong>${esc(borrowerName(c)||'Borrower')}</strong></a></td><td data-label="Amount" class="money">${fmt(c.amount_paise)}</td><td data-label="Status"><span class="yesterday-status yesterday-status-${c.status.toLowerCase()}">${c.status==='PENDING'?'Awaiting result':c.status==='PASSED'?'Passed':'Bounced'}</span></td><td data-label="Actions">${c.status==='PENDING'?`<div class="result-actions"><button class="cheque-result" data-id="${esc(c.id)}" data-status="PASSED">Passed</button><button class="cheque-result" data-id="${esc(c.id)}" data-status="BOUNCED">Bounced</button></div>`:`<span class="result-done">Result confirmed</span>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No cheques for this date.');
  const subtitle=view==='today'?'Scheduled deposit worklist. Deposit status is not recorded here; bank results are confirmed separately.':view==='yesterday'?'Confirm Passed or Bounced only after the bank result is known.':view==='upcoming'?`Scheduled tomorrow through ${esc(report.weekEnd)}.`:'Pending and bounced items remain visible until resolved.';
  const chequeCompact=paise=>{const rupees=Number(paise)/100;if(rupees>=10000000)return '₹'+(rupees/10000000).toFixed(2)+'Cr';if(rupees>=100000)return '₹'+(rupees/100000).toFixed(2)+'L';return fmt(paise);};
const yesterdayContent=view==='yesterday'?`<div class="yesterday-page"><header class="yesterday-heading"><h1>Yesterday's Cheques</h1><p>Review and confirm cheque results.</p></header><section class="yesterday-overview" aria-label="Cheque results for selected date"><div class="yesterday-date"><span class="yesterday-label">Cheque date</span><strong>${esc(shortDate(report.date))}</strong><label for="chequeDate">Change date</label><input id="chequeDate" type="date" value="${esc(report.date)}"></div><div class="yesterday-stat"><span class="yesterday-label">Total cheques</span><strong>${report.count}</strong></div><div class="yesterday-stat"><span class="yesterday-label">Results confirmed</span><strong>${report.rows.filter(c=>c.status==='PASSED'||c.status==='BOUNCED').length}</strong></div><div class="yesterday-stat yesterday-amount"><span class="yesterday-label">Total amount</span><strong title="${fmt(report.amount)}">${chequeCompact(report.amount)}</strong></div></section><section class="yesterday-older"><div><strong>Older pending</strong><span>${older.count} ${older.count===1?'cheque':'cheques'} awaiting results</span><span>${fmt(older.amount)}</span></div><a href="#/cheques/older?date=${encodeURIComponent(report.date)}">Review older pending</a></section><section class="yesterday-results"><div class="yesterday-table-head"><h2>Cheque Results</h2><input id="chequeSearch" type="search" placeholder="Search borrower..." aria-label="Search borrower"></div>${yesterdayTable}<p id="yesterdayVisibleCount" class="yesterday-visible-count">Showing ${report.count} ${report.count===1?'cheque':'cheques'}</p></section></div>`:null;
const olderContent=view==='older'?`<div class="yesterday-page older-pending-page"><header class="yesterday-heading"><h1>Older Pending</h1><p>Confirm the bank result for earlier cheque dates.</p></header><section class="yesterday-overview" aria-label="Older pending cheque summary"><div class="yesterday-date"><span class="yesterday-label">Before date</span><strong>${esc(shortDate(report.date))}</strong><label for="chequeDate">Change cutoff date</label><input id="chequeDate" type="date" value="${esc(report.date)}"></div><div class="yesterday-stat"><span class="yesterday-label">Cheques awaiting result</span><strong>${report.count}</strong></div><div class="yesterday-stat yesterday-amount"><span class="yesterday-label">Total amount</span><strong title="${fmt(report.amount)}">${chequeCompact(report.amount)}</strong></div></section><section class="yesterday-results"><div class="yesterday-table-head"><h2>Pending results</h2><input id="chequeSearch" type="search" placeholder="Search borrower..." aria-label="Search borrower"></div>${yesterdayTable}<p id="yesterdayVisibleCount" class="yesterday-visible-count">Showing ${report.count} ${report.count===1?'cheque':'cheques'}</p></section></div>`:null;
  const todayCompact=chequeCompact;
  const scheduleDate=value=>{const [year,month,day]=value.split('-');return `${Number(day)} ${['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][Number(month)-1]} ${year.slice(-2)}`;};
  const scheduleEnd=report.endDate||report.date;
